import {lanternCodeSource} from './lantern-codes-content.mjs';
import {codeView,startCodes,resumeCodes,editCodes,shareCodes,supportCodes,runCodeTest,keepCodes,removeCodes,assessDesign,beats,validCodeTest,validKeptCode} from './lantern-codes-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attr,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attr}>${esc(label)}</button>`;
const pages={learn:'Meet the lantern',build:'Make a code',send:'Send to Dot',compare:'Compare for the job'};
const label=(s,id)=>s.messages.find(m=>m.id===id)?.label??id;
const strip=p=>p?`<span class="code-strip" role="img" aria-label="${[...p].map(c=>c==='S'?'short':'long').join(', ')}">${[...p].map(c=>`<span class="code-bit ${c==='S'?'short':'long'}" aria-hidden="true">${c==='S'?'Short':'Long'}</span>`).join('')}</span>`:'<span class="code-empty">No flashes</span>';
export const codesEntry=()=>'<aside class="codes-entry"><h2>Lantern Codes</h2><p>Agree on a code with Dot, send a message, then try the pretend rain.</p><a class="secondary" href="#post/codes">Climb the Signal Tower</a></aside>';
function tower(){return `<svg class="codes-tower" viewBox="0 0 640 165" aria-hidden="true" focusable="false"><path d="M0 138Q110 95 210 135T440 131T640 135V165H0Z" fill="#344e55"/><g stroke="#c5d5d1" fill="#476a72" stroke-width="3"><path d="M68 132V63L113 25l45 38v69M470 132V45l38-28 38 28v87"/><path d="M57 64h112M461 46h95"/><rect x="94" y="65" width="37" height="42" rx="13" fill="#edbd61"/><rect x="493" y="52" width="29" height="38" rx="10" fill="#edbd61"/></g><path d="M180 77Q310 20 449 63" fill="none" stroke="#edbd61" stroke-width="3" stroke-dasharray="4 13"/><text x="113" y="154" text-anchor="middle">Your lantern</text><text x="508" y="154" text-anchor="middle">Dot’s window</text></svg>`;}
function card(s,p,title){return `<section class="codes-card"><h3>${esc(title)}</h3>${p===null?'<p>No card shared yet.</p>':`<dl>${s.messages.map(m=>`<div><dt>${esc(m.label)}</dt><dd>${p[m.id]?strip(p[m.id]):'Not assigned'}</dd></div>`).join('')}</dl>`}</section>`;}
const readableTests=w=>Array.isArray(w.tests)?w.tests.filter(validCodeTest):[];
const fresh=(t,w)=>JSON.stringify([t.source,t.patterns,t.card,t.rain])===JSON.stringify([w.source,w.patterns,w.card,w.rain])&&(t.kind==='all'||t.selected===w.selected);
function result(t,w){const current=fresh(t,w),row=t.rows.find(r=>r.id===t.selected)??t.rows[0],goal=current&&t.kind==='all'&&t.rain&&t.rows.length===t.source.messages.length&&t.rows.every(r=>r.outcome==='read');return `<section class="codes-result" data-code-result data-code-kind="${t.kind}"><h2 id="code-result-heading" tabindex="-1">${current?'What Dot could read':'An earlier test · your current setup has changed'}</h2><p>${t.kind==='all'?'All-message test':'Single framed message'} · ${t.rain?'Pretend rain':'Clear weather'}</p>${t.rows.map(r=>`<article><h3>You meant: ${esc(label(t.source,r.id))}</h3><p>Dot saw: ${strip(r.observed)}</p>${t.kind==='all'&&r.outcome==='read'?'':`<p>${esc(r.feedback)}</p>`}${r.candidates.length?`<p>Meanings on Dot’s card: <strong>${r.candidates.map(id=>esc(label(t.source,id))).join(' or ')}</strong>.</p>`:''}</article>`).join('')}${row?.observed?`<div class="codes-trace"><h3>Step through Dot’s visible flashes</h3><div class="codes-visible">${strip(row.observed)}</div>${btn('data-code-trace','Next visible flash')}<p data-code-trace-text role="status">A stationary picture; advance at your own pace.</p></div>`:''}${goal?`<p class="codes-goal" role="status">${esc(t.source.copy.goal)}</p>`:''}</section>`;}
function comparison(w){const rows=[{title:'Your code',patterns:w.patterns},...w.source.presets];return `<section class="codes-comparison"><h2>Compare with a matching card</h2><p>This reference gives each design its own matching receiver card. Your actual tests still use Dot’s real copy.</p><div class="codes-table-wrap"><table><thead><tr><th>Design</th><th>Sender beats, once each</th><th>Clear</th><th>Pretend rain</th></tr></thead><tbody>${rows.map(p=>{const clear=assessDesign(w.source,p.patterns,false),rain=assessDesign(w.source,p.patterns,true);return `<tr><th>${esc(p.title)}</th><td>${clear.complete?'': 'Partial: '}${clear.totalBeats}</td><td>${clear.works?'Distinct':'Incomplete or overlapping'}</td><td>${rain.works?'Distinct and visible':'Invisible or overlapping'}</td></tr>`;}).join('')}</tbody></table></div><p>Which would be easiest to remember? Tell someone why. The best choice depends on the job.</p>${w.source.presets.map(p=>`<details><summary>${esc(p.title)} · see its patterns</summary>${card(w.source,p.patterns,p.title)}${btn(`data-code-start="${esc(p.id)}" data-code-preset`,'Try a copy in a new visit')}</details>`).join('')}</section>`;}
function history(w){const tests=readableTests(w),kept=Array.isArray(w.kept)?w.kept.filter(validKeptCode):[];return `<details class="codes-history"><summary>Earlier tests and kept designs</summary><p>${tests.length} readable tests; ${kept.length} readable kept designs. Older versions stay separate from current edits.</p>${kept.map((k,i)=>`<details><summary>Kept design ${i+1}</summary>${card(k.source,k.patterns,'Your kept code')}${card(k.source,k.card,'Dot’s kept card')}<p>${k.rain?'Pretend rain':'Clear weather'}</p></details>`).join('')}${tests.map((t,i)=>`<details><summary>Test ${i+1} · ${t.rain?'rain':'clear'}</summary>${t.rows.map(r=>`<p>${esc(label(t.source,r.id))}: ${esc(r.feedback)} ${r.candidates.map(id=>esc(label(t.source,id))).join(' / ')}</p>`).join('')}<p>Frozen sender total: ${t.totalBeats} beats.</p></details>`).join('')}<p>Unreadable earlier entries, if any, remain exact in your notebook download.</p></details>`;}
export function codesPage(state){
 const v=codeView(state),w=v.work,s=w?.source??lanternCodeSource;
 const head=`<div class="codes-page" data-codes-root><header><a class="back" href="#post">Willow Post Office</a><h1>Lantern Codes</h1><p>Send a meaning. Test what arrives.</p>${tower()}</header>`;
 if(v.status==='unavailable')return head+'<h2 id="code-heading" tabindex="-1">Earlier lantern work is retained</h2><p>This version cannot edit that format. Download notes; other activities stay open.</p><a class="secondary" href="#notes">Open notes</a></div>';
 const visits=v.visits.length?`<details class="codes-visits"><summary>Your code visits</summary>${v.visits.map(x=>x.readable?btn(`data-code-resume="${esc(x.id)}"`,`${x.title} · ${x.id}`):'<p>An unreadable visit stays in your download.</p>').join('')}</details>`:'';
 const choices=`<div class="codes-actions">${btn('data-code-start="blank"','Start a new blank code')}${v.visits.filter(x=>x.readable).map(x=>btn(`data-code-remove="${esc(x.id)}"`,`Remove ${x.id}`)).join('')}</div>`;
 if(!w)return head+`<section class="codes-intro"><h2 id="code-heading" tabindex="-1">Can Dot read your message?</h2><p>${esc(s.copy.welcome)}</p><p>${esc(s.copy.learn)}</p>${btn('data-code-start="blank"','Start a code',true)}</section>${visits}<p class="codes-limit">${esc(s.copy.limit)}</p><p id="code-status" role="status"></p></div>`;
 const pattern=w.patterns[w.selected]??'',last=readableTests(w).at(-1);
 const select=`<div class="codes-message-choices" role="group" aria-label="Choose a message">${s.messages.map(m=>btn(`data-code-select="${esc(m.id)}" aria-pressed="${w.selected===m.id}"`,m.label)).join('')}</div>`;
 const weather=`<div class="codes-actions" role="group" aria-label="Weather">${btn(`data-code-weather="clear" aria-pressed="${!w.rain}"`,'Clear weather')}${btn(`data-code-weather="rain" aria-pressed="${w.rain}"`,'Pretend rain')}</div>`;
 const shared=`<p class="codes-shared">${w.card===null?'Dot has no card yet.':JSON.stringify(w.card)===JSON.stringify(w.patterns)?'Dot has a copy of this card.':'Your card has changed. Dot still has the earlier copy.'}</p>${btn('data-code-share','Give Dot this card',true)}`;
 let body='';
 if(w.page==='learn')body=`<h2 id="code-heading" tabindex="-1">Meet the lantern</h2><p>${esc(s.copy.welcome)}</p><p>${esc(s.copy.learn)}</p><aside class="codes-guided">${esc(s.copy.guided)}</aside>${btn('data-code-page="build"','Make your code',true)}`;
 if(w.page==='build')body=`<h2 id="code-heading" tabindex="-1">Make a code</h2><p>${esc(s.copy.build)}</p>${select}<div class="codes-editor"><h3>${esc(label(s,w.selected))}</h3>${strip(pattern)}<p>${pattern?beats(pattern,s.rules):0} sender beats · up to ${s.rules.maxFlashes} flashes</p><div class="codes-actions">${btn(`data-code-append="S" ${pattern.length>=s.rules.maxFlashes?'disabled':''}`,'Add short')}${btn(`data-code-append="L" ${pattern.length>=s.rules.maxFlashes?'disabled':''}`,'Add long')}${btn(`data-code-pop ${!pattern?'disabled':''}`,'Remove last')}${btn(`data-code-clear ${!pattern?'disabled':''}`,'Clear this pattern')}</div></div>${card(s,w.patterns,'Your code card')}${shared}<details><summary>Dot’s actual copy</summary>${card(s,w.card,'Dot’s card')}</details>${btn('data-code-page="send"','Send a message',true)}`;
 if(w.page==='send')body=`<h2 id="code-heading" tabindex="-1">Send to Dot</h2><p>${esc(s.copy.send)}</p>${select}${weather}<section class="codes-sending"><h3>Your signal for ${esc(label(s,w.selected))}</h3>${strip(pattern)}<p>Sender cost: ${beats(pattern,s.rules)} beats. Dot gets no clues from hidden places or waiting time.</p>${btn('data-code-test="send"','Send this message',true)}</section>${shared}<details><summary>Compare your two cards</summary><div class="codes-card-pair">${card(s,w.patterns,'Your code')}${card(s,w.card,'Dot’s actual card')}</div></details>${last?result(last,w):'<p>No message sent yet. Choose a pattern, share a card if you want, then send.</p>'}`;
 if(w.page==='compare')body=`<h2 id="code-heading" tabindex="-1">Compare for the job</h2><p>${esc(s.copy.compare)}</p>${weather}${shared}${btn('data-code-test="all"','Test all messages with Dot',true)}${last?result(last,w):''}${comparison(w)}`;
 return head+`<nav class="codes-pages" aria-label="Lantern turns">${Object.entries(pages).map(([key,title])=>btn(`data-code-page="${key}" aria-current="${w.page===key?'step':'false'}"`,title)).join('')}</nav>${visits}<section class="codes-turn">${body}</section><div class="codes-actions">${btn('data-code-keep','Keep this design')}${btn('data-code-help="help"','Help')}${btn('data-code-help="example"','Different example')}${btn('data-code-help="together"','We’re working together')}</div>${['help','example'].filter(k=>w.support.includes(k)).map(k=>`<aside class="codes-help"><h3>${k==='help'?'Help':'A different example'}</h3><p>${esc(s.copy[k])}</p></aside>`).join('')}<details><summary>Count the sender beats</summary><p>${esc(s.copy.cost)}</p></details>${hearButton(s.copy[w.page==='learn'?'learn':w.page],'Hear this turn')}<p class="codes-limit">${esc(s.copy.limit)}</p>${history(w)}<details><summary>Start another visit or make space</summary><p>A copy or blank visit keeps your current design. Removing a visit requires confirmation and removes its tests and kept designs.</p>${choices}<a class="secondary" href="#notes">Download notes first</a></details><p id="code-status" role="status" tabindex="-1"></p><footer><a class="secondary" href="#pathways/science">Other science</a><a class="secondary" href="#post">Return to the Post Office</a></footer></div>`;
}
export function codesNotes(state){if(!Object.hasOwn(state,'lanternCodes'))return '';const v=codeView(state);return `<details class="panel"><summary>Lantern Codes · model designs and tests</summary><p>Computer-model results, not independent decoding, calculation, physical device building or mastery. Support requests and original results stay separate.</p>${v.visits.filter(x=>x.readable).map(x=>{const w=state.lanternCodes.visits[x.id];return `<h3>${esc(x.id)}</h3>${card(w.source,w.patterns,'Current code')}${history(w)}`;}).join('')}<details><summary>Exact saved sources and work, including retained formats</summary><pre>${esc(JSON.stringify(state.lanternCodes,null,2))}</pre></details></details>`;}
export function bindCodes(state,{save,render,focus,canExport,explorerId,isActive}={}){
 const root=document.querySelector('[data-codes-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport};let step=0;
 const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive());
 const say=text=>{const node=root.querySelector('#code-status');if(node)node.textContent=text;};
 const act=(el,fn,message='',target='#code-heading')=>{if(!live(el))return;const r=fn();if(!r?.ok){say(r?.error??'This change was not kept.');return;}stopSpeech();save?.();render?.();const node=document.querySelector('#code-status');if(node)node.textContent=message;focus?.(target);};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 on('[data-code-start]',b=>act(b,()=>{const w=codeView(state).work;return startCodes(state,b.dataset.codeStart,b.hasAttribute('data-code-preset')&&w?{...o,source:w.source}:o);},'New visit opened; your earlier code stays kept.'));
 on('[data-code-resume]',b=>act(b,()=>resumeCodes(state,b.dataset.codeResume,o),'Earlier visit resumed with its own source.'));
 on('[data-code-page]',b=>act(b,()=>editCodes(state,'page',b.dataset.codePage,o)));
 on('[data-code-select]',b=>act(b,()=>editCodes(state,'select',b.dataset.codeSelect,o),'',`[data-code-select="${b.dataset.codeSelect}"]`));
 on('[data-code-weather]',b=>act(b,()=>editCodes(state,'rain',b.dataset.codeWeather==='rain',o),'Weather changed. Earlier test results stay unchanged.',`[data-code-weather="${b.dataset.codeWeather}"]`));
 on('[data-code-append]',b=>act(b,()=>editCodes(state,'append',b.dataset.codeAppend,o),'Pattern saved.',`[data-code-append="${b.dataset.codeAppend}"]`));
 on('[data-code-pop]',b=>act(b,()=>editCodes(state,'pop',null,o),'Last flash removed.'));
 on('[data-code-clear]',b=>act(b,()=>editCodes(state,'clear',null,o),'Only this pattern was cleared.'));
 on('[data-code-share]',b=>act(b,()=>shareCodes(state,o),'Dot has a new copy of your card.','[data-code-share]'));
 on('[data-code-test]',b=>act(b,()=>runCodeTest(state,b.dataset.codeTest,o),'Model test kept.','#code-result-heading'));
 on('[data-code-keep]',b=>act(b,()=>keepCodes(state,o),'A separate design snapshot is kept.','[data-code-keep]'));
 on('[data-code-help]',b=>act(b,()=>supportCodes(state,b.dataset.codeHelp,o),'Support request kept.',`[data-code-help="${b.dataset.codeHelp}"]`));
 on('[data-code-remove]',b=>{const v=codeView(state),w=v.root?.visits[b.dataset.codeRemove];if(!w)return;const count=x=>Array.isArray(x)?String(x.length):'retained unreadable';if(window.confirm(`Remove ${b.dataset.codeRemove}, including ${count(w.tests)} tests and ${count(w.kept)} kept designs? Download notes first if you want to keep them. Other visits stay unchanged.`))act(b,()=>removeCodes(state,b.dataset.codeRemove,true,o),'Selected visit removed.');});
 on('[data-code-trace]',b=>{const w=codeView(state).work,t=w&&readableTests(w).at(-1),row=t?.rows.find(r=>r.id===t.selected)??t?.rows[0];if(!row?.observed)return;const r=supportCodes(state,'trace',o);if(!r.ok){say(r.error);return;}save?.();const i=step++%row.observed.length;root.querySelectorAll('.codes-visible .code-bit').forEach((bit,j)=>bit.classList.toggle('pointed',j===i));const text=root.querySelector('[data-code-trace-text]');if(text)text.textContent=`Visible flash ${i+1} of ${row.observed.length}: ${row.observed[i]==='S'?'short':'long'}.`;});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(!b)return;if(!live(b)){e.stopImmediatePropagation();return;}const r=supportCodes(state,'audio',o);if(!r.ok){e.stopImmediatePropagation();say(r.error);}else save?.();},true);
}
